#[local] Abbreviation cellA := (cell AsanUbsan.M.loaded_segments).
#[local] Abbreviation wrA := (wr AsanUbsan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

(* [comment removed for export] *)
Definition art_gs_malloc_sec {FSG : Type} (G : art_gs FSG) (parr msz r u n : Z) (kb : nat) : art_gs FSG :=
  GS FSG (g_log FSG G ++ art_sec_events msz r parr (Z.of_nat (length (g_sec FSG G))) (g_sec_committed FSG G)) (g_inited FSG G)
     (g_cls FSG G) (g_st FSG G) (g_sec FSG G ++ [SEC r msz u n false]) true (g_qt FSG G) (g_qg FSG G) kb (g_ia FSG G) (g_fs FSG G).

(* [comment removed for export] *)
Definition art_malloc_out_sec (rn : art_run) (M M' : word -> option byte) (S n rz qz qn m8 nd msz r nch : Z) (committed : bool) (kb : nat) (b1 : Z) : Prop :=
  let ab := 4096 + r in
  mem_grows M M'
  /\ art_agree (art_malloc3L_fp S (rn_t rn) (rn_parr rn) nch r msz (rn_l2 rn) (rn_blk rn) committed) M M'
  /\ (forall (x : word) b, art_shlo r <= U x < art_shhi r msz -> ~ (Pm5ArtPoison.SB + r / 8 <= U x < Pm5ArtPoison.SB + r / 8 + msz / 8) -> M x = Some b -> M' x = Some b)
  /\ DInvD (rn_l2 rn) (rn_blk rn) kb M'
  /\ wrA M' r msz /\ wrA M' (Pm5ArtPoison.SB + r / 8) (msz / 8)
  /\ cellA M' r 8 r /\ cellA M' (r + 8) 8 msz /\ cellA M' (r + 16) 8 nd /\ cellA M' (r + 24) 8 nch
  /\ 0 <= b1 < 256 /\ b1 mod 4 = 1
  /\ cellA M' (ab + rz - 16) 1 2 /\ cellA M' (ab + rz - 15) 1 b1 /\ cellA M' (ab + rz - 14) 2 (n / 2 ^ 32) /\ cellA M' (ab + rz - 12) 4 n     (* [comment removed for export] *)
  /\ (forall j, 0 <= j < qn -> cellA M' (2147450880 + ab / 8 + 2 * qz + j) 1 0) /\ (m8 <> 0 -> cellA M' (2147450880 + ab / 8 + 2 * qz + qn) 1 m8)
  /\ cellA M' 0x16a198 8 4096 /\ cellA M' (0x16a198 + 8) 8 (rn_parr rn) /\ cellA M' (0x16a198 + 16) 8 (rn_parr rn) /\ cellA M' (0x16a198 + 56) 8 (nch + 1)
  /\ cellA M' (0x16a198 + 48) 8 16384 /\ cellA M' (0x16a198 + 616) 4 0
  /\ cellA M' (rn_parr rn + 8 * nch) 8 r /\ wrA M' (rn_parr rn) 131072.

Lemma art_live_sec_events : forall log msz r parr nch cm, art_live (log ++ art_sec_events msz r parr nch cm) = (r, msz) :: art_live log.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SF0!1+0+1!2+5+2+2!1+01!1,:+1|30;!1,>4!1,>|A00000;!2,;!2'<#4!2'=5#36!3,81!4,?+2+2#5#6!1'6#7!2,9#5#4!1'6#6!2'A9:$l;R2!3+42#18!3,81!4,?+2+2#4#5:!2,B2=!3,8+193!3'7+1#6?!1'6@!2'C#69!2,;!2'<#3!2'=5#26!3,8+1C3!3'7+1@D$log;R0$msz;R+2$r;R+2$parr;R+2$nch;R+2$cm;R+3vd-3RN$b;R+3!3+42!1'6!3'7+1#7!3,8+1!2,9#6#5-3RN$committed;R+30#123!3,8+1738#12!6'@2;<>AB!6'@0E$l;R0!3+42!1'6#18!6'@2!2'ACA<!6'@2;$l;R2!3+42!2'A7#18>AB!1'6E!2'C@C!3'7+1#6!3'7+1?D!4'D+1#6?D!3+42!1'6!3'7+1#6!5'E#5#4#3#2#1=").
Qed.

